function pyrepr(x){
  if (Object.is(x,-0)) return '-0.0';
  if (x===0) return '0.0';
  const m=/^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(Math.abs(x).toExponential());
  const D=m[1]+(m[2]||''), E=parseInt(m[3]);
  let s;
  if (E<-4||E>=16) s=D[0]+(D.length>1?'.'+D.slice(1):'')+'e'+(E<0?'-':'+')+String(Math.abs(E)).padStart(2,'0');
  else if (E>=0) s = D.length<=E+1 ? D+'0'.repeat(E+1-D.length)+'.0' : D.slice(0,E+1)+'.'+D.slice(E+1);
  else s='0.'+'0'.repeat(-E-1)+D;
  return (x<0?'-':'')+s;
}
module.exports={pyrepr};
EOF
cat > gen.js <<'EOF'
const {pyrepr}=require('./ref.js');
const buf=Buffer.alloc(8);
const out=[];
function emit(x){
  if(!Number.isFinite(x)) return;
  let inp;
  try { inp = x.toPrecision(17); } catch(e){ return; }
  if (Number(inp)!==x) inp = x.toExponential(); // fallback
  out.push(inp+'\t'+pyrepr(x));
}
// random bit patterns
for(let i=0;i<1500;i++){
  for(let j=0;j<8;j++) buf[j]=Math.floor(Math.random()*256);
  emit(buf.readDoubleLE(0));
}
// magnitude sweep
for(let e=-320;e<=308;e++){ for(const k of [1,1.5,2,3,9,9.99,9.999999999999999,1.0000000000000002,5,7.3]) emit(k*Math.pow(10,e)); }
// ulp walks around thresholds
for(const base of [1e16,1e-4,1e-5,1e15,1e21,1e-7,1e-6,1e17,9007199254740992,1e-323,Number.MAX_VALUE,Number.MIN_VALUE,2.2250738585072014e-308]){
  let x=base;
  for(let i=0;i<25;i++){ emit(x); x=nextAfter(x,Infinity); }
  x=base;
  for(let i=0;i<25;i++){ x=nextAfter(x,-Infinity); emit(x); }
}
function nextAfter(x,dir){
  if(x===0) return dir>0?Number.MIN_VALUE:-Number.MIN_VALUE;
  const b=Buffer.alloc(8); b.writeDoubleLE(x,0);
  let bi=b.readBigUInt64LE(0);
  const up=(dir>x)===(x>0);
  bi += (x>0? (dir>x?1n:-1n) : (dir>x?-1n:1n));
  b.writeBigUInt64LE(bi,0); return b.readDoubleLE(0);
}
// i/7, i*0.1, powers of 2
for(let i=1;i<=400;i++){ emit(i/7); emit(i*0.1); emit(i*3); }
for(let i=-1074;i<=1023;i++) emit(Math.pow(2,i));
console.log(out.join('\n'));
EOF
